package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.jobs.*;import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;
import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
class ProviderMonitoringCycleTest {
 static final Key KEY=new Key("OPS-08","java","fictional-provider");
 ProviderReadinessTelemetry.Evidence ready(OperationalPersistenceFixture f){return new ProviderReadinessTelemetry.Evidence(f.clock.now,ProviderReadinessTelemetry.Status.READY);}
 ProviderCallTelemetry.Evidence calls(OperationalPersistenceFixture f,long n,long age,long blocked){return new ProviderCallTelemetry.Evidence(f.clock.now,n,age,blocked);}
 ProviderMonitoringCycle cycle(OperationalPersistenceFixture f,ProviderReadinessTelemetry.Api account,ProviderCallTelemetry.Api api){var store=f.store();var value=new ProviderMonitoringCycle(KEY,account,api,new ProviderEvidence(),store,f.monitor(store),()->new OperationalMonitoringService.Configuration(1,MonitoringFixtures.complete()),f.clock);value.start();return value;}
 @Test void completeNormalCommitsOnceAndRestartSkipsBothProviders(){var f=new OperationalPersistenceFixture();var account=new AtomicInteger();var sql=new AtomicInteger();ProviderReadinessTelemetry.Api a=()->{account.incrementAndGet();assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return ready(f);};ProviderCallTelemetry.Api c=()->{sql.incrementAndGet();return calls(f,0,0,0);};assertEquals(ProviderMonitoringCycle.Outcome.SAMPLED,cycle(f,a,c).tick());assertEquals(Status.NORMAL,f.store().read(KEY).status());assertEquals("0",f.store().read(KEY).observedValue());assertEquals(ProviderMonitoringCycle.Outcome.ALREADY_SAMPLED,cycle(f,a,c).tick());assertEquals(1,account.get());assertEquals(1,sql.get());}
 @Test void readinessAndNativeConfigurationFailureBlockAndReadyNeverClaimsHistoricalRepair(){var f=new OperationalPersistenceFixture();cycle(f,()->new ProviderReadinessTelemetry.Evidence(f.clock.now,ProviderReadinessTelemetry.Status.CREDENTIAL_REJECTED),()->calls(f,0,0,0)).tick();assertEquals(java.util.Set.of(Guard.DISPATCH_AI),f.store().read(KEY).guards());f.clock.now=f.clock.now.plusSeconds(60);cycle(f,()->null,()->calls(f,0,0,0)).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());assertFalse(f.store().read(KEY).guards().isEmpty());for(int n=0;n<4;n++){f.clock.now=f.clock.now.plusSeconds(60);cycle(f,()->ready(f),()->calls(f,0,0,0)).tick();assertFalse(f.store().read(KEY).guards().isEmpty());assertEquals(1,f.store().read(KEY).counters().get("provider_failed"));}var second=new OperationalPersistenceFixture();cycle(second,()->ready(second),()->calls(second,0,0,1)).tick();assertFalse(second.store().read(KEY).guards().isEmpty());}
 @Test void unknownAgeThresholdUsesOriginalValueAndDoesNotCreateExplicitFailure(){var f=new OperationalPersistenceFixture();cycle(f,()->ready(f),()->calls(f,1,86400,0)).tick();assertEquals(Level.WARNING,f.store().read(KEY).level());assertEquals("86400",f.store().read(KEY).observedValue());assertTrue(f.store().read(KEY).guards().isEmpty());}
 @Test void missingNativeFactsSkipNetworkAndCrossMinuteOrAcquisitionFailuresStayUnknown(){var f=new OperationalPersistenceFixture();cycle(f,()->{fail("SQL unknown must not issue account GET");return ready(f);},()->null).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());f.clock.now=f.clock.now.plusSeconds(60);cycle(f,()->{f.clock.now=f.clock.now.plusSeconds(60);return ready(f);},()->calls(f,0,0,0)).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());f.clock.now=f.clock.now.plusSeconds(60);cycle(f,()->{throw new IllegalStateException("fictional unavailable");},()->calls(f,0,0,0)).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(KEY).status());}
 @Test void singleFlightStopAndInterruptDuringNetworkNeverWriteLateState()throws Exception{var f=new OperationalPersistenceFixture();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var value=cycle(f,()->{entered.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){Thread.currentThread().interrupt();}return ready(f);},()->calls(f,0,0,0));var executor=Executors.newSingleThreadExecutor();try{var first=executor.submit(value::tick);assertTrue(entered.await(5,TimeUnit.SECONDS));assertEquals(ProviderMonitoringCycle.Outcome.BUSY,value.tick());value.stop();release.countDown();assertEquals(ProviderMonitoringCycle.Outcome.STOPPED,first.get(5,TimeUnit.SECONDS));assertNull(f.store().read(KEY));}finally{release.countDown();executor.shutdownNow();}}
}
